 "content": "from collections import Counter

def transform(grid):
    """Connect matching non-background markers along their shared rows/columns."""
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    markers = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value != background]
    marker_color = Counter(grid[r][c] for r, c in markers).most_common(1)[0][0]
    markers = [(r, c) for r, c in markers if grid[r][c] == marker_color]
    out = [row[:] for row in grid]
    rows, cols = {}, {}
    for r, c in markers:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)
    for r, cs in rows.items():
        for c in range(min(cs), max(cs) + 1):
            if out[r][c] == background:
                out[r][c] = 3
    for c, rs in cols.items():
        for r in range(min(rs), max(rs) + 1):
            if out[r][c] == background:
                out[r][c] = 3
    return out
